final class Node {
    var val: Int
    var next: Node?
    init(_ val: Int, _ next: Node? = nil) { self.val = val; self.next = next }
}
func reverse(_ head: Node?) -> Node? {
    var prev: Node? = nil
    var curr = head
    while let n = curr {
        let nextTemp = n.next
        n.next = prev
        prev = n
        curr = nextTemp
    }
    return prev
}
