final class ListNode {
    var val: Int
    var next: ListNode?
    init(_ val: Int, _ next: ListNode? = nil) { self.val = val; self.next = next }
}

func reverseLinkedList(_ head: ListNode?) -> ListNode? {
    var prev: ListNode? = nil
    var curr = head
    while let node = curr {
        let nextTemp = node.next
        node.next = prev
        prev = node
        curr = nextTemp
    }
    return prev
}

let list = ListNode(1, ListNode(2, ListNode(3)))
let rev = reverseLinkedList(list)
var vals: [Int] = []
var c = rev
while let n = c { vals.append(n.val); c = n.next }
print(vals)

final class ListNode {
    var val: Int
    var next: ListNode?
    init(_ val: Int, _ next: ListNode? = nil) { self.val = val; self.next = next }
}

func hasCycle(_ head: ListNode?) -> Bool {
    var slow = head
    var fast = head
    while let f = fast, let nextNode = f.next {
        slow = slow?.next
        fast = nextNode.next
        if slow === fast {
            return true
        }
    }
    return false
}

let n1 = ListNode(1)
let n2 = ListNode(2)
n1.next = n2
n2.next = n1
print(hasCycle(n1))
print(hasCycle(ListNode(1, ListNode(2))))

final class ListNode {
    var val: Int
    var next: ListNode?
    init(_ val: Int, _ next: ListNode? = nil) { self.val = val; self.next = next }
}

func findMiddleNode(_ head: ListNode?) -> ListNode? {
    var slow = head
    var fast = head
    while let f = fast, let nextNode = f.next {
        slow = slow?.next
        fast = nextNode.next
    }
    return slow
}

let listOdd = ListNode(1, ListNode(2, ListNode(3, ListNode(4, ListNode(5)))))
let listEven = ListNode(1, ListNode(2, ListNode(3, ListNode(4))))
print(findMiddleNode(listOdd)?.val ?? -1)
print(findMiddleNode(listEven)?.val ?? -1)
